const nextPlanVersion = `-- name: NextPlanVersion :one
SELECT (COALESCE(MAX(version_number), 0) + 1)::integer AS next_version
FROM plans
WHERE organisation_id = $1 AND assignment_id = $2
`

type NextPlanVersionParams struct {
	OrganisationID string
	AssignmentID   string
}

func (q *Queries) NextPlanVersion(ctx context.Context, arg NextPlanVersionParams) (int32, error) {
	row := q.db.QueryRowContext(ctx, nextPlanVersion, arg.OrganisationID, arg.AssignmentID)
	var next_version int32
	err := row.Scan(&next_version)
	return next_version, err
}

